var a=`1137-waldorf-salad`;var n=`world-1137`;var t=`US`;var r=`northern-america`;var s=4;var d=34;var l={en:`Waldorf Salad`,ua:`Салат «Вальдорф»`};var o={en:`Waldorf Salad is a dish from United States prepared with apple, celery stalk, red grape, mayonnaise. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Салат «Вальдорф», страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: яблуко, стебло селери, червоний виноград, майонез. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var p=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:9,i:[[`apple`,3,`pcs`],[`celery-stalk`,210,`g`],[`red-grape`,200,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`mayonnaise`,150,`g`],[`lemon-juice`,35,`ml`],[`ground-black-pepper`,3,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:3,i:[[`walnut`,120,`g`]]},{en:`Chill briefly if appropriate, garnish with the listed ingredients and serve at the intended temperature.`,ua:`За потреби недовго охолодіть, прикрасьте зазначеними складниками й подавайте за потрібної температури.`,t:[`garnishing`],m:15,i:[[`lettuce`,150,`g`]]}];var g={slug:a,id:n,country:`US`,region:r,servings:4,minutes:34,title:l,text:o,steps:p};export{t as country,g as default,n as id,d as minutes,r as region,s as servings,a as slug,p as steps,o as text,l as title};